WHERE tenant_id = #{tenantId}
  AND org_id = #{orgId}
  AND people_id = #{peopleId}
  AND is_deleted = 0
LIMIT 1

SELECT FROM care_chat_thread WHERE tenant_id = #{tenantId} AND is_deleted = 0 AND people_id IN
#{pid}
ORDER BY COALESCE(last_message_at, gmt_created) DESC

